def edit_distance(a: str, b: str) -> int:
    if len(a) < len(b):
        a, b = b, a

    m, n = len(a), len(b)
    if n == 0:
        return m

    prev = list(range(n + 1))

    for i in range(1, m + 1):
        curr = [i] + [0] * n
        ai = a[i - 1]

        for j in range(1, n + 1):
            cost = 0 if ai == b[j - 1] else 1
            curr[j] = min(
                prev[j] + 1,
                curr[j - 1] + 1,
                prev[j - 1] + cost
            )

        prev = curr

    return prev[n]

from itertools import zip_longest

def compare_versions(v1: str, v2: str) -> int:
    p1 = [int(x) for x in v1.split('.')]
    p2 = [int(x) for x in v2.split('.')]

    for a, b in zip_longest(p1, p2, fillvalue=0):
        if a < b:
            return -1
        if a > b:
            return 1

    return 0

def compare_versions(v1: str, v2: str) -> int:
    parts1 = v1.split(".")
    parts2 = v2.split(".")
    length = max(len(parts1), len(parts2))

    for i in range(length):
        a = int(parts1[i]) if i < len(parts1) else 0
        b = int(parts2[i]) if i < len(parts2) else 0

        if a < b:
            return -1
        if a > b:
            return 1

    return 0

import functools

def retry(times: int, exceptions=(Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
            if last_exc is not None:
                raise last_exc
        return wrapper
    return decorator

import heapq

def topo_sort(nodes: list, edges: list[tuple]) -> list:
    node_set = set(nodes)

    adjacency = {node: set() for node in node_set}
    indegree = {node: 0 for node in node_set}

    for a, b in edges:
        if a in node_set and b in node_set and b not in adjacency[a]:
            adjacency[a].add(b)
            indegree[b] += 1

    heap = [node for node in node_set if indegree[node] == 0]
    heapq.heapify(heap)

    result = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(node_set):
        raise ValueError("Cycle detected")

    return result

